#define N 1000

// Exploiting Locality for Cache Efficiency

// Registers/L1: Smallest, Fastest
// L3/Main Memory: Slowest, Largest

void access_matrix_optimized(int M[N][N]) {
    // 1. Temporal Locality: M[i] data reused quickly
    for (int i = 0; i < N; i++) {
        // 2. Spatial Locality: Row access (j) is sequential
        //    (Cache line loading prefetches nearby elements)
        for (int j = 0; j < N; j++) {
            M[i][j] *= 2;
        }
    }
}
